def evolve(state: str, offsets: list[int], t: int) -> str:
    n = len(state)
    if t == 0:
        return state

    value = int(state[::-1], 2)
    mask = (1 << n) - 1
    shifts = [offset % n for offset in offsets]

    while t:
        if t & 1:
            result = 0
            for shift in shifts:
                if shift:
                    result ^= (value >> shift) | ((value << (n - shift)) & mask)
                else:
                    result ^= value
            value = result

        t >>= 1
        if t:
            shifts = [(shift * 2) % n for shift in shifts]

    return format(value, f"0{n}b")[::-1]
